export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeHtml;
export const atEnd=(time,max)=>Number.isFinite(time)&&Number.isFinite(max)&&max>0&&time>0&&time>=max*(1-1e-8);
export function pageWindow(current,total){
 const count=Math.max(1,Math.floor(total)||1),page=Math.max(1,Math.min(count,Math.floor(current)||1));
 if(count<=7)return Array.from({length:count},(_,i)=>i+1);
 const selected=new Set([1,count,page-1,page,page+1]);
 if(page<=3)for(const n of [2,3,4])selected.add(n);
 if(page>=count-2)for(const n of [count-3,count-2,count-1])selected.add(n);
 const values=[...selected].filter(n=>n>=1&&n<=count).sort((a,b)=>a-b),result=[];
 for(const n of values){if(result.length&&n-result.at(-1)>1)result.push(null);result.push(n);}return result;
}
export function parameterText(value,unit=''){return Number.isFinite(value)?value.toLocaleString('vi-VN',{maximumFractionDigits:6})+(unit?' '+unit:''):'Chưa xác định';}
export const layoutDefaults={controlsWidth:292,dockWidth:380,chartHeight:280,tableHeight:260,controlsCollapsed:false,dockCollapsed:false,exploreDock:false,guidance:false,chartCollapsed:false,tableCollapsed:false};
export function cleanLayout(raw={}){raw=raw&&typeof raw==='object'?raw:{};const x={...layoutDefaults};for(const [k,min,max]of [['controlsWidth',220,340],['dockWidth',320,600],['chartHeight',220,520],['tableHeight',160,600]])if(Number.isFinite(+raw[k]))x[k]=Math.max(min,Math.min(max,+raw[k]));for(const k of ['controlsCollapsed','dockCollapsed','exploreDock','guidance','chartCollapsed','tableCollapsed'])if(typeof raw[k]==='boolean')x[k]=raw[k];return x;}
export function restorableRow(e,row){if(!row||!row.s||typeof row.s!=='object'||!e.params.every(p=>Object.hasOwn(row.s,p.key)&&Number.isFinite(row.s[p.key])&&row.s[p.key]>=p.min-1e-6&&(p.key==='t'||row.s[p.key]<=p.max+1e-6)))return false;if(e.id==='electric'&&![0,1,2,3].includes(row.c?.mode))return false;if(e.id==='capacitor'&&!['charge','discharge'].includes(row.c?.capMode))return false;return true;}
export function rowMatches(e,row,s,c){if(!restorableRow(e,row))return false;if(!e.params.every(p=>Math.abs(row.s[p.key]-(s[p.key]??0))<=1e-8*Math.max(1,Math.abs(s[p.key]??0))))return false;return e.id==='electric'?row.c.mode===c.mode:e.id==='capacitor'?row.c.capMode===c.capMode:true;}
const colors={blue:'#3566b9',orange:'#a5632c',green:'#247b65',purple:'#7952a8'};
export function metricColor(e,key,index=0){if(e.id==='energy')return {k:colors.orange,u:colors.blue,total:colors.green}[key]||colors.blue;if(['vector_sum','vector_components'].includes(e.id))return {result:colors.green,fx:colors.blue,fy:colors.orange}[key]||colors.blue;if(['x','height','distance','voltage','potential'].includes(key))return colors.blue;if(['v','speed','kinetic'].includes(key))return colors.orange;if(['acc','alpha'].includes(key))return colors.purple;return [colors.blue,colors.orange,colors.purple][index%3];}
export function dragParameter(e,key){const map={'source-voltage':['u','voltage','emf','source1','input','peak'].find(k=>e.params.some(p=>p.key===k)),'source-voltage-fine':['u','voltage','emf','source1','input','peak'].find(k=>e.params.some(p=>p.key===k)),q1:'x1',q2:'x2',p:'px',height:'h0','energy-height':'h0','circular-radius':'radius','pendulum-length':'length','standing-probe':'probeX','oscillator-amplitude':'a','wave-amplitude':'a','gas-volume':'v','freefall-height':'h0','launch-angle':'angle','ramp-angle':'angle','optics-angle':'angle','work-angle':'angle','wire-angle':'angle','image-distance':'distance','polarization-angle':'angle','pressure-depth':'depth','buoyancy-depth':'fraction','fringe-probe':'probe','thermal-length':'length','spring-load':'m','interference-probe':'probeX'};return key?.startsWith('param:')?key.slice(6):map[key]||key;}
export function toolDescription(e,s,key){const p=e.params.find(p=>p.key===dragParameter(e,key));if(!p)return null;const fmt=v=>Number.isFinite(v)?v.toLocaleString('vi-VN',{maximumFractionDigits:4}):'—';if(key==='interference-probe')return {label:'Đầu dò giao thoa P',value:`x = ${fmt(s.probeX)} m · z = ${fmt(s.probeZ)} m`,hint:'Kéo đầu dò trên mặt phẳng quan sát; nhập tọa độ trong thiết lập.'};if(e.id==='electric'&&['q1','q2','p'].includes(key)){const q=key==='q1'?'Điện tích q₁':key==='q2'?'Điện tích q₂':'Đầu dò P',x=key==='q1'?'x1':key==='q2'?'x2':'px',y=key==='q1'?'y1':key==='q2'?'y2':'py';return {label:q,value:`x = ${fmt(s[x])} m · y = ${fmt(s[y])} m`,hint:'Kéo trên mặt phẳng XY; đổi z trong thiết lập.'};}return {label:p.label,value:`${fmt(s[p.key])}${p.unit?' '+p.unit:''}`,hint:key==='source-voltage-fine'?'Xoay núm tinh chỉnh điện áp.':'Kéo để đổi giá trị; có thể dùng ô số hoặc phím mũi tên.'};}
const supers=Object.fromEntries([... '⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁼⁽⁾ⁿ'].map((c,i)=>[c,[...'0123456789+-=()n'][i]])),subs=Object.fromEntries([...'₀₁₂₃₄₅₆₇₈₉₊₋'].map((c,i)=>[c,[...'0123456789+-'][i]]));
function scriptMath(text){const tokens=[];for(let i=0;i<text.length;i++){const c=text[i];if((supers[c]||subs[c])&&tokens.length){const isSup=!!supers[c];let value='';while(i<text.length&&(isSup?supers[text[i]]:subs[text[i]])){value+=(isSup?supers:subs)[text[i++]];}i--;const base=tokens.pop();tokens.push(`<${isSup?'msup':'msub'}>${base}<mtext>${esc(value)}</mtext></${isSup?'msup':'msub'}>`);}else if(c==='½')tokens.push('<mfrac><mn>1</mn><mn>2</mn></mfrac>');else if(/[=+−×·/;≤≥]/.test(c))tokens.push(`<mo>${esc(c)}</mo>`);else if(c===' ')tokens.push('<mspace width=".24em"/>');else tokens.push(`<mtext>${esc(c)}</mtext>`);}return tokens.join('');}
export function formulaMarkup(e){return `<div class="math-formula"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block" aria-label="${esc(e.formula)}"><mrow>${scriptMath(e.formula)}</mrow></math><span class="formula-fallback">${esc(e.formula)}</span></div>`;}
export function previewMarkup(e,readouts,image='',icon='◌'){return `<div class="quick-preview"><div class="preview-image">${image?`<img src="${esc(image)}" alt="Mô hình ${esc(e.shortTitle)}">`:`<span aria-hidden="true">${icon}</span>`}<span>Ảnh mô hình minh họa</span></div><div class="preview-meta">Lớp ${e.grade} · ${esc(e.topic)}${e.extra?' · Mở rộng':''}</div><p>${esc(e.description)}</p><p class="preview-state-label">Số đọc ở thiết lập ban đầu</p><div class="preview-readings">${readouts.map(m=>`<div><span>${esc(m.label)}</span><b>${esc(m.value)} <small>${esc(m.unit)}</small></b></div>`).join('')}</div><details><summary>Quan hệ & điều kiện</summary>${formulaMarkup(e)}<p>${esc(e.limit)}</p></details><a class="button primary" href="#lab/${e.id}">Mở thí nghiệm →</a></div>`;}
export function timeCaption(e){return e.visualOnly?'Đốm sáng minh họa chậm · không dùng để đo vận tốc ánh sáng':e.playSeconds||e.timeScale&&e.timeScale!==1?'Phát theo tốc độ mô phỏng · đồng hồ hiển thị thời gian của mô hình':e.atlas?'Biểu diễn nguyên lí · hình có thể thay đổi tỉ lệ':'Mô hình lí tưởng · xem điều kiện trước khi kết luận';}
